                .HasColumnName("Status_ID");
            entity.Property(e => e.StatusLabel)
                .HasMaxLength(39)
                .IsUnicode(false)
                .HasComputedColumnSql("(case when [CPPP]=(4) AND [Ready_to_Approve]=(0) then 'Draft' when [Deputy]=(4) AND [Ready_to_Approve]=(0) then 'Draft' when [PIC]=(4) AND [Ready_to_Approve]=(0) then 'Draft' when [CPPP]=(4) then 'CPPP Pending' when [Deputy]=(4) then 'Deputy Pending' when [PIC]=(4) then 'PIC Pending' when [CPPP]=(3) AND [Deputy]=(3) AND [PIC]=(3) then 'CPPP, Deputy and PIC Rejected' when [CPPP]=(3) then 'CPPP Rejected' when [Deputy]=(3) then 'Deputy Rejected' when [PIC]=(3) then 'PIC Rejected' when [CPPP]=(2) AND [Deputy]=(2) then 'CPPP, Deputy and PIC returned to review' when [CPPP]=(2) then 'CPPP returned to review' when [Deputy]=(2) then 'Deputy returned to review' when [PIC]=(2) then 'PIC returned to review' when [Deputy]=(1) AND [CPPP]=(1) then 'Approved' when [Deputy]=(1) then 'CPPP Pending' when [PIC]=(1) then 'Deputy Pending' when [Professional_standards] IS NOT NULL then 'PIC Pending' when [Ready_to_Approve]=(1) then 'Form Pending' when [Ready_to_Approve]=(0) then 'Draft' else 'Pending' end)", true)
                .HasColumnName("Status_Label");
